                ("MetaMathQA", 98750, "math"),
                ("Daring Anteater (advanced non-chat subset)", 17082, "various"),
            ]


@dataclass
class PreferenceDataConfig:
    """Configuration for preference tuning data (Table 3)."""
    sources: List[Tuple[str, int]] = None

    def __post_init__(self):
        if self.sources is None:
            self.sources = [
                ("UltraFeedback (binarized, filtered)", 60800),
            ]


class SFTDataset(Dataset):
    """Dataset for Supervised Fine-Tuning.

    Loads instruction-tuning data in chat format.
    Filters samples to max length of 4096 tokens.
    Aggregates loss at token level (following Muennighoff et al., 2024).
    """

    def __init__(
        self,
        data_path: str,
        tokenizer,
        max_seq_len: int = 4096,
    ):
        self.data_path = data_path
        self.tokenizer = tokenizer
        self.max_seq_len = max_seq_len

        self.samples = self._load_data()

    def _load_data(self) -> List[Dict]:
        """Load SFT data from JSONL file.

        Expected format: {"messages": [{"role": "user", "content": "..."},
                                        {"role": "assistant", "content": "..."}]}
        """
        samples = []
        try:
            if self.data_path.endswith(".gz"):
                opener = gzip.open
            else:
                opener = open

            with opener(self.data_path, "rt", encoding="utf-8") as f:
                for line in f:
                    sample = json.loads(line)
                    # Filter by length
                    text = self._format_messages(sample.get("messages", []))
                    tokens = self.tokenizer.encode(text)
                    if len(tokens) <= self.max_seq_len:
                        samples.append(sample)
        except FileNotFoundError:
            print(f"Warning: SFT data not found at {self.data_path}")

        return samples

    def _format_messages(self, messages: List[Dict]) -> str:
        """Format chat messages into a single string.

        Uses a simple chat template (in practice, this would use the
        model's chat template).
        """
        parts = []
        for msg in messages:
            role = msg.get("role", "user")
            content = msg.get("content", "")
            if role == "user":
                parts.append(f"User: {content}")
            elif role == "assistant":
                parts.append(f"Assistant: {content}")
            else:
                parts.append(content)
        return "\n".join(parts)

    def __len__(self) -> int:
        return len(self.samples)

    def __getitem__(self, idx: int) -> Dict[str, torch.Tensor]:
        """Get tokenized SFT sample with loss masking.

        Only the assistant responses contribute to the loss.
        """
        sample = self.samples[idx]
        messages = sample.get("messages", [])

        # Tokenize with special handling for assistant tokens
        input_ids = []
        labels = []

        for msg in messages:
            role = msg.get("role", "user")
            content = msg.get("content", "")

            if role == "user":
                prefix = f"User: {content}\n"
            elif role == "assistant":
                prefix = f"Assistant: {content}\n"
            else:
                prefix = content

            tokens = self.tokenizer.encode(prefix)

            if role == "assistant":
                # Assistant tokens contribute to loss
                input_ids.extend(tokens)
                labels.extend(tokens)
            else:
                # User/system tokens are masked
                input_ids.extend(tokens)
                labels.extend([-100] * len(tokens))

        # Pad/truncate to max_seq_len
        if len(input_ids) > self.max_seq_len:
            input_ids = input_ids[:self.max_seq_len]
            labels = labels[:self.max_seq_len]
        else:
            pad_len = self.max_seq_len - len(input_ids)
            input_ids = input_ids + [self.tokenizer.pad_token_id or 0] * pad_len
            labels = labels + [-100] * pad_len

        return {
            "input_ids": torch.tensor(input_ids, dtype=torch.long),
            "labels": torch.tensor(labels, dtype=torch.long),
        }


